import limited_client as robot, numpy as np
print('status',robot.status())
for c in (2,0):
 o=robot.observe(camera=c); r=o['robot']; print('camera',c,'robot',r)
 if c==2:
  K=o['intrinsic']; T=o['camera_to_world']; D=o['depth_m']
  for u,v in [(70,245),(100,250),(130,250),(160,255),(190,260),(220,265),(260,270),(300,270),(330,350)]:
   z=float(D[v,u]); p=T@np.array([(u-K[0,2])*z/K[0,0],(v-K[1,2])*z/K[1,1],z,1]); print((u,v),round(z,3),np.round(p[:3],3))
